Here's a modern, responsive HTML loading page with a spinning loader and smooth transitions:

```html
<!DOCTYPE html>
<html lang="en">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <title>Loading Page</title>
    <style>
        * {
            margin: 0;
            padding: 0;
            box-sizing: border-box;
        }

        body {
            font-family: 'Segoe UI', Tahoma, Geneva, Verdana, sans-serif;
            background: linear-gradient(135deg, #1a1a2e 0%, #16213e 100%);
            height: 100vh;
            display: flex;
            justify-content: center;
            align-items: center;
            overflow: hidden;
        }

        .loader-container {
            text-align: center;
            color: white;
        }

        .spinner {
            width: 60px;
            height: 60px;
            margin: 0 auto 20px;
            position: relative;
        }

        .spinner::before,
        .spinner::after {
            content: "";
            position: absolute;
            border-radius: 50%;
            animation: spin 1.5s cubic-bezier(0.68, -0.55, 0.27, 1.55) infinite;
        }

        .spinner::before {
            border: 4px solid rgba(255, 255, 255, 0.1);
            width: 100%;
            height: 100%;
            top: 0;
            left: 0;
        }

        .spinner::after {
            border: 4px solid #4ecca3;
            width: 70%;
            height: 70%;
            top: 15%;
            left: 15%;
            animation-delay: 0.5s;
        }

        .loading-text {
            font-size: 18px;
            letter-spacing: 2px;
            text-transform: uppercase;
            animation: fade 1s infinite alternate;
        }

        .percentage {
            font-size: 14px;
            color: #a0a0a0;
            margin-top: 10px;
            animation: fade 1.5s infinite alternate;
        }

        @keyframes spin {
            0% {
                transform: rotate(0deg);
            }
            100% {
                transform: rotate(360deg);
            }
        }

        @keyframes fade {
            0% {
                opacity: 0.4;
            }
            100% {
                opacity: 1;
                text-shadow: 0 0 10px rgba(78, 204, 163, 0.7);
            }
        }

        /* Responsive adjustments */
        @media (max-width: 600px) {
            .spinner {
                width: 40px;
                height: 40px;
            }

            .spinner::after {
                width: 70%;
                height: 70%;
                top: 15%;
                left: 15%;
            }

            .loading-text {
                font-size: 16px;
            }
        }
    </style>
</head>
<body>
    <div class="loader-container">
        <div class="spinner"></div>
        <h1 class="loading-text">Loading</h1>
        <div class="percentage" id="percentage">0%</div>
    </div>

    <script>
        // Simulate loading progress
        let progress = 0;
        const percentageDisplay = document.getElementById('percentage');

        const loadingInterval = setInterval(() => {
            // Random progress increment for realistic feel
            const increment = Math.floor(Math.random() * 5) + 1;
            progress = Math.min(progress + increment, 100);

            percentageDisplay.textContent = `${progress}%`;

            // Animation for progress text
            if (progress < 100) {
                percentageDisplay.style.opacity = 0.5 + (progress / 200);
            }

            if (progress === 100) {
                clearInterval(loadingInterval);

                // Simulate loading complete
                setTimeout(() => {
                    // Here you would redirect to your main content
                    // For demo purposes, we'll just log it
                    console.log("Loading complete!");

                    // Optional: Create a fade-out effect
                    document.querySelector('.loader-container').style.opacity = '0';
                    setTimeout(() => {
                        // Replace with your main content or redirect
                        // window.location.href = '/dashboard';
                        document.querySelector('.loader-container').style.display = 'none';
                        document.body.innerHTML = `
                            <div style="text-align:center; color: white; padding: 20px;">
                                <h1>Welcome!</h1>
                                <p>Content loaded successfully.</p>
                            </div>
                        `;
                    }, 500);
                }, 800);
            }
        }, 100);
    </script>
</body>
</html>
```

**Features of this loading page**:
- Smooth spinning loader animation with two layers for visual depth
- Gradient background for a modern look
- Animated loading text with subtle glow effect
- Dynamic percentage counter that increments realistically
- Fully responsive design for mobile and desktop
- JavaScript simulation of loading progress with completion transition
- Dark theme with accent color (#4ecca3) for visual appeal

To use this, simply save the code as an `.html` file and open it in your browser. For production use, replace the JavaScript completion logic with your actual page content loading event.

Here's a simple and efficient Python function to check if a number is prime:

```python
def is_prime(n):
    if n <= 1:
        return False
    if n <= 3:
        return True
    if n % 2 == 0 or n % 3 == 0:
        return False

    # Check divisors from 5 up to √n, skipping even numbers and multiples of 3
    i = 5
    while i * i <= n:
        if n % i == 0 or n % (i + 2) == 0:
            return False
        i += 6

    return True

# Example usage:
number = int(input("Enter a number: "))
if is_prime(number):
    print(f"{number} is a prime number.")
else:
    print(f"{number} is not a prime number.")
```

This implementation has O(√n) time complexity and handles edge cases correctly.

If you need a prime number generator (listing all primes up to a limit), here's a simple version using the Sieve of Eratosthenes:

```python
def sieve_of_eratosthenes(limit):
    primes = []
    is_prime = [True] * (limit + 1)
    is_prime[0] = is_prime[1] = False

    for i in range(2, int(limit**0.5) + 1):
        if is_prime[i]:
            for j in range(i*i, limit + 1, i):
                is_prime[j] = False

    for i in range(2, limit + 1):
        if is_prime[i]:
            primes.append(i)

    return primes

# Example usage:
limit = 100
print(f"Primes up to {limit}: {sieve_of_eratosthenes(limit)}")
